SELECT status, COUNT(*) as count, COALESCE(SUM(total_cost), 0) as totalCost FROM jsh_production_order WHERE delete_flag = '0'
AND tenant_id = #{tenantId,jdbcType=BIGINT}
GROUP BY status ORDER BY status

SELECT DATE_FORMAT(create_time, '%Y-%m-%d') as date, COUNT(*) as orderCount, COALESCE(SUM(total_cost), 0) as totalCost, COALESCE(SUM(material_cost), 0) as materialCost, COALESCE(SUM(labor_cost), 0) as laborCost FROM jsh_production_order WHERE delete_flag = '0' AND create_time BETWEEN #{beginTime,jdbcType=VARCHAR} AND #{endTime,jdbcType=VARCHAR}
AND tenant_id = #{tenantId,jdbcType=BIGINT}
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d') ORDER BY date

SELECT

FROM jsh_production_order
WHERE delete_flag = '0'

    AND tenant_id = #{tenantId,jdbcType=BIGINT}


    AND order_no LIKE CONCAT('%', #{orderNo,jdbcType=VARCHAR}, '%')


    AND status = #{status,jdbcType=VARCHAR}


    AND material_id = #{materialId,jdbcType=BIGINT}


    AND sales_order_id = #{salesOrderId,jdbcType=BIGINT}


    AND create_time >= #{beginTime,jdbcType=VARCHAR}


    AND create_time <= #{endTime,jdbcType=VARCHAR}

ORDER BY create_time DESC

SELECT COUNT(*)
FROM jsh_production_order
WHERE delete_flag = '0'

    AND tenant_id = #{tenantId,jdbcType=BIGINT}


    AND order_no LIKE CONCAT('%', #{orderNo,jdbcType=VARCHAR}, '%')


    AND status = #{status,jdbcType=VARCHAR}


    AND material_id = #{materialId,jdbcType=BIGINT}


    AND sales_order_id = #{salesOrderId,jdbcType=BIGINT}


